from pathlib import Path

path = Path(".env")
text = path.read_text(encoding="utf-8")
lines = text.splitlines()
wanted = {
    "AWS_REGION": "us-east-1",
    "LLM_MODEL_STRONG": "us.anthropic.claude-sonnet-4-20250514-v1:0",
    "LLM_MODEL_FAST": "us.anthropic.claude-sonnet-4-20250514-v1:0",
}
seen: set[str] = set()
out: list[str] = []
for line in lines:
    if not line.strip() or line.lstrip().startswith("#") or "=" not in line:
        out.append(line)
        continue
    key, _, _val = line.partition("=")
    key = key.strip()
    if key in wanted:
        out.append(f"{key}={wanted[key]}")
        seen.add(key)
    else:
        out.append(line)

insert_after = None
for i, line in enumerate(out):
    if line.startswith("AWS_REGION="):
        insert_after = i
        break

extras = []
for key in ("AWS_ACCESS_KEY_ID", "AWS_SECRET_ACCESS_KEY"):
    if not any(l.startswith(f"{key}=") for l in out):
        extras.append(f"{key}=")

if extras and insert_after is not None:
    out[insert_after + 1 : insert_after + 1] = extras
elif extras:
    out.extend(extras)

for key, value in wanted.items():
    if key not in seen and not any(l.startswith(f"{key}=") for l in out):
        out.append(f"{key}={value}")

path.write_text("\n".join(out) + "\n", encoding="utf-8")
print("updated_model_and_region=yes")
for name in [
    "NEATLOGS_API_KEY",
    "AWS_ACCESS_KEY_ID",
    "AWS_SECRET_ACCESS_KEY",
    "AWS_REGION",
    "LLM_MODEL_STRONG",
    "LLM_MODEL_FAST",
]:
    for line in out:
        if line.startswith(name + "="):
            val = line.split("=", 1)[1]
            print(f"{name}={'set' if val.strip() else 'empty'}")
            break
    else:
        print(f"{name}=missing")

