"""Web fetch/search, HTML to text, and light link discovery. v0: httpx + BeautifulSoup."""

from __future__ import annotations

import re
from urllib.parse import urljoin, urlparse

import httpx
from bs4 import BeautifulSoup

USER_AGENT = "SignalSDR/0.1 (+neatHack research; local demo)"
MAX_PAGES = 8
FETCH_TIMEOUT = 20.0


def normalize_url(url: str) -> str:
    url = url.strip()
    if not url.startswith(("http://", "https://")):
        url = "https://" + url
    return url.rstrip("/")


def domain_of(url: str) -> str:
    host = urlparse(normalize_url(url)).netloc.lower()
    if host.startswith("www."):
        host = host[4:]
    return host


def html_to_text(html: str, max_chars: int = 12000) -> str:
    soup = BeautifulSoup(html, "html.parser")
    for tag in soup(["script", "style", "noscript", "svg"]):
        tag.decompose()
    text = " ".join(soup.get_text(" ", strip=True).split())
    return text[:max_chars]


def fetch_url(url: str, *, client: httpx.Client | None = None) -> tuple[str | None, str | None]:
    """Return (final_url, text) or (None, None) on failure."""
    owns = client is None
    client = client or httpx.Client(
        timeout=FETCH_TIMEOUT,
        follow_redirects=True,
        headers={"User-Agent": USER_AGENT},
    )
    try:
        response = client.get(normalize_url(url))
        if response.status_code >= 400:
            return None, None
        ctype = response.headers.get("content-type", "")
        if "html" not in ctype and "text" not in ctype:
            return None, None
        return str(response.url), html_to_text(response.text)
    except httpx.HTTPError:
        return None, None
    finally:
        if owns:
            client.close()


def onsite_candidate_urls(home: str) -> list[str]:
    """Homepage plus common seller pages, same host only."""
    home = normalize_url(home)
    host = domain_of(home)
    paths = [
        "",
        "/pricing",
        "/customers",
        "/customers/case-studies",
        "/case-studies",
        "/about",
        "/about-us",
        "/product",
        "/products",
    ]
    urls: list[str] = []
    for path in paths:
        candidate = home if path == "" else home + path
        if domain_of(candidate) == host and candidate not in urls:
            urls.append(candidate)
    return urls[:MAX_PAGES]


def discover_more_onsite(home: str, html: str, limit: int = 4) -> list[str]:
    soup = BeautifulSoup(html, "html.parser")
    host = domain_of(home)
    found: list[str] = []
    keywords = ("pricing", "customer", "case", "about", "product")
    for a in soup.find_all("a", href=True):
        href = a["href"]
        full = urljoin(home + "/", href)
        if domain_of(full) != host:
            continue
        low = full.lower()
        if any(k in low for k in keywords) and full not in found:
            found.append(normalize_url(full))
        if len(found) >= limit:
            break
    return found


def fetch_seller_pages(website: str) -> list[dict]:
    """Fetch up to MAX_PAGES on-site pages. Each item: url, text."""
    home = normalize_url(website)
    pages: list[dict] = []
    seen: set[str] = set()
    with httpx.Client(
        timeout=FETCH_TIMEOUT,
        follow_redirects=True,
        headers={"User-Agent": USER_AGENT},
    ) as client:
        # seed from known paths; also parse homepage for more links
        queue = onsite_candidate_urls(home)
        while queue and len(pages) < MAX_PAGES:
            url = queue.pop(0)
            if url in seen:
                continue
            seen.add(url)
            final_url, text = fetch_url(url, client=client)
            if not final_url or not text:
                continue
            pages.append({"url": final_url, "text": text})
            if len(pages) == 1:
                # only have text; re-fetch raw html for link discovery cheaply
                try:
                    raw = client.get(final_url)
                    if raw.status_code < 400:
                        for extra in discover_more_onsite(home, raw.text):
                            if extra not in seen and extra not in queue:
                                queue.append(extra)
                except httpx.HTTPError:
                    pass
    return pages


_CUSTOMER_HINT = re.compile(
    r"(?:customers?|case stud(?:y|ies)|trusted by|companies that|used by)\s*[:\-–]?\s*(.+)",
    re.I,
)


def heuristic_named_customers(pages: list[dict], limit: int = 12) -> list[str]:
    """Very naive name harvesting for v0; LLM refines later."""
    names: list[str] = []
    for page in pages:
        for match in _CUSTOMER_HINT.finditer(page["text"][:4000]):
            chunk = match.group(1)[:200]
            parts = re.split(r"[,|/]| and ", chunk)
            for part in parts:
                name = part.strip(" .•·")
                if 2 <= len(name) <= 40 and name[0].isupper() and name not in names:
                    names.append(name)
                if len(names) >= limit:
                    return names
    return names

"""Product researcher: seller brief and evidence cards from the seller site."""

from __future__ import annotations

import json
import re
from typing import Any
from urllib.parse import urlparse

from pydantic import BaseModel, Field

from app.agents.evidence import make_evidence
from app.llm import get_llm
from app.models import SellerBrief
from app.tools import web
from app.tools.crustdata import CrustdataClient, CrustdataError


class _ExtractedSeller(BaseModel):
    one_liner: str = ""
    products: list[str] = Field(default_factory=list)
    value_props: list[str] = Field(default_factory=list)
    pricing_notes: str | None = None
    named_customers: list[str] = Field(default_factory=list)


def _domain(website: str) -> str:
    return web.domain_of(website)


def product_researcher_node(state: dict[str, Any]) -> dict[str, Any]:
    """v0: fetch site, identify/enrich seller, LLM extract into SellerBrief."""
    inp = state["input"]
    campaign_id = state["campaign_id"]
    company_name = inp["company_name"]
    website = inp["website"]
    description = inp.get("description") or ""
    events = list(state.get("events") or [])
    errors = list(state.get("errors") or [])

    client = CrustdataClient()
    domain = _domain(website)
    evidence = []
    pages = web.fetch_seller_pages(website)
    page_blob = "\n\n".join(f"URL: {p['url']}\n{p['text'][:3000]}" for p in pages)[:14000]

    for page in pages[:3]:
        snippet = page["text"][:160]
        if snippet:
            evidence.append(
                make_evidence(
                    snippet,
                    source_type="web",
                    source_ref=page["url"],
                    confidence="medium",
                )
            )

    seller_id = None
    try:
        identified = client.company_identify(
            {"domains": [domain]},
            campaign_id=campaign_id,
            step="product.identify",
        )
        # response shapes vary; try common paths
        seller_id = _first_company_id(identified)
        if seller_id:
            enriched = client.company_enrich(
                {
                    "crustdata_company_ids": [seller_id],
                    "fields": [
                        "basic_info",
                        "taxonomy",
                        "headcount",
                        "funding",
                        "locations",
                        "competitors",
                    ],
                },
                campaign_id=campaign_id,
                step="product.enrich",
            )
            company_data = _first_company_data(enriched)
            if company_data:
                name = (company_data.get("basic_info") or {}).get("name") or company_name
                evidence.append(
                    make_evidence(
                        f"Crustdata profile for {name} ({domain})",
                        source_type="crustdata",
                        source_ref=f"crustdata:/company/enrich:basic_info",
                        confidence="high",
                    )
                )
    except CrustdataError as exc:
        errors.append({"step": "product_researcher", "error": str(exc)})
        events.append({"type": "error", "step": "product_researcher", "detail": str(exc)})

    heuristic_customers = web.heuristic_named_customers(pages)
    llm = get_llm("fast")
    prompt = (
        "Extract seller facts from the page text. Named customers must appear in the text; "
        "never invent customers. Return JSON matching the schema.\n"
        f"Company: {company_name}\nWebsite: {website}\nDescription: {description}\n\n"
        f"Heuristic customer candidates: {heuristic_customers}\n\n"
        f"PAGE TEXT:\n{page_blob or '(no pages fetched)'}"
    )
    try:
        structured = llm.with_structured_output(_ExtractedSeller)
        extracted = structured.invoke(prompt)
        if not isinstance(extracted, _ExtractedSeller):
            extracted = _ExtractedSeller.model_validate(extracted)
    except Exception as exc:  # noqa: BLE001 — v0 soft-fail to heuristics
        errors.append({"step": "product_researcher.llm", "error": str(exc)})
        extracted = _ExtractedSeller(
            one_liner=description or f"{company_name} product",
            products=[company_name],
            value_props=[description] if description else [],
            named_customers=heuristic_customers[:8],
        )

    named = []
    for name in extracted.named_customers:
        clean = name.strip()
        if clean and clean.lower() not in {company_name.lower(), domain} and clean not in named:
            named.append(clean)

    # identify customer names (free)
    if named:
        try:
            cust_ids = client.company_identify(
                {"names": named[:25]},
                campaign_id=campaign_id,
                step="product.customers_identify",
            )
            kept_names = _confident_customer_names(cust_ids, named)
            if kept_names:
                named = kept_names
                events.append(
                    {
                        "type": "product.customers_identified",
                        "count": len(kept_names),
                    }
                )
        except CrustdataError as exc:
            errors.append({"step": "product.customers_identify", "error": str(exc)})

    if not named:
        events.append({"type": "product.no_customers", "detail": "buyer_finder will use low-confidence ICP"})

    for name in named[:8]:
        evidence.append(
            make_evidence(
                f"Named customer on seller site: {name}",
                source_type="web",
                source_ref=pages[0]["url"] if pages else website,
                confidence="medium",
            )
        )

    brief = SellerBrief(
        company_name=company_name,
        domain=domain,
        one_liner=extracted.one_liner or description or company_name,
        products=extracted.products or [company_name],
        value_props=extracted.value_props or [],
        pricing_notes=extracted.pricing_notes,
        named_customers=named,
        evidence=evidence,
    )
    client.close()
    return {
        "seller": brief.model_dump(mode="json"),
        "events": events,
        "errors": errors,
        "budget": {"credits_spent": CrustdataClient().ledger.spent(campaign_id)},
    }


def _first_company_id(payload: Any) -> int | str | None:
    if isinstance(payload, list) and payload:
        item = payload[0]
        if isinstance(item, dict):
            return item.get("crustdata_company_id") or item.get("company_id") or item.get("id")
    if isinstance(payload, dict):
        if "crustdata_company_id" in payload:
            return payload["crustdata_company_id"]
        companies = payload.get("companies") or payload.get("results") or []
        if companies and isinstance(companies[0], dict):
            return companies[0].get("crustdata_company_id") or companies[0].get("id")
        # identify enrich-style
        for block in payload if False else []:
            pass
        matches = payload.get("matches") or []
        if matches and isinstance(matches[0], dict):
            data = matches[0].get("company_data") or matches[0]
            return data.get("crustdata_company_id") or data.get("company_id")
        # nested identify array response
        for key in ("data", "items"):
            inner = payload.get(key)
            found = _first_company_id(inner)
            if found:
                return found
    return None


def _first_company_data(payload: Any) -> dict | None:
    if isinstance(payload, list) and payload:
        item = payload[0]
        if isinstance(item, dict):
            matches = item.get("matches") or []
            if matches and isinstance(matches[0], dict):
                return matches[0].get("company_data") or matches[0]
            return item.get("company_data") or item
    if isinstance(payload, dict):
        matches = payload.get("matches") or []
        if matches and isinstance(matches[0], dict):
            return matches[0].get("company_data") or matches[0]
    return None


def _confident_customer_names(payload: Any, originals: list[str]) -> list[str]:
    """Keep identify matches with confidence >= 0.9 when available."""
    kept: list[str] = []
    rows: list[dict] = []
    if isinstance(payload, list):
        rows = [r for r in payload if isinstance(r, dict)]
    elif isinstance(payload, dict):
        rows = [r for r in (payload.get("companies") or payload.get("results") or []) if isinstance(r, dict)]
        if not rows and "matches" in payload:
            rows = [r for r in payload["matches"] if isinstance(r, dict)]

    for row in rows:
        conf = row.get("confidence") or row.get("confidence_score") or row.get("score")
        name = row.get("name") or (row.get("basic_info") or {}).get("name")
        domain = row.get("domain") or row.get("primary_domain") or (row.get("basic_info") or {}).get("primary_domain")
        if conf is not None and float(conf) < 0.9:
            continue
        if domain or name:
            label = name or next((o for o in originals if o.lower() in json.dumps(row).lower()), None)
            if label and label not in kept:
                kept.append(label)
    # if API did not return confidence, fall back to originals that look like brands
    if not kept:
        return [n for n in originals if re.search(r"[A-Za-z]", n)][:8]
    return kept[:8]

"""Buyer finder: ICP proposal and lookalike company candidates (v0: no human gate)."""

from __future__ import annotations

from collections import Counter
from typing import Any

from pydantic import BaseModel, Field

from app.agents.evidence import make_evidence
from app.llm import get_llm
from app.models import BuyerRole, Company, ICPProposal, SellerBrief
from app.tools.crustdata import CrustdataClient, CrustdataError


class _IcpDraft(BaseModel):
    industries: list[str] = Field(default_factory=list)
    countries: list[str] = Field(default_factory=list)
    employee_count_ranges: list[str] = Field(default_factory=list)
    funding_stages: list[str] = Field(default_factory=list)
    economic_buyer_titles: list[str] = Field(default_factory=list)
    champion_titles: list[str] = Field(default_factory=list)
    rationale: str = ""


def buyer_finder_node(state: dict[str, Any]) -> dict[str, Any]:
    """v0: enrich named customers, derive ICP via LLM, search companies, keep top N."""
    campaign_id = state["campaign_id"]
    n = int(state["input"].get("n") or 10)
    seller = SellerBrief.model_validate(state["seller"])
    events = list(state.get("events") or [])
    errors = list(state.get("errors") or [])
    client = CrustdataClient()

    customer_ids: list[int] = []
    if seller.named_customers:
        try:
            identified = client.company_identify(
                {"names": seller.named_customers[:25]},
                campaign_id=campaign_id,
                step="buyer.customers_identify",
            )
            customer_ids = _collect_ids(identified)
        except CrustdataError as exc:
            errors.append({"step": "buyer.customers_identify", "error": str(exc)})

    customer_profiles: list[dict] = []
    if customer_ids:
        try:
            enriched = client.company_enrich(
                {
                    "crustdata_company_ids": customer_ids[:25],
                    "fields": ["basic_info", "taxonomy", "headcount", "locations", "funding"],
                },
                campaign_id=campaign_id,
                step="buyer.customers_enrich",
            )
            customer_profiles = _collect_company_data(enriched)
        except CrustdataError as exc:
            errors.append({"step": "buyer.customers_enrich", "error": str(exc)})

    industries = _top_values(customer_profiles, _industry)
    countries = _top_values(customer_profiles, _country)
    ranges = _top_values(customer_profiles, _employee_range)

    llm = get_llm("strong")
    prompt = (
        "Propose an ICP for lookalike outbound. Prefer industries/countries/size bands "
        "from the customer profiles when present. If customers are missing, mark that in rationale.\n"
        f"Seller: {seller.company_name} — {seller.one_liner}\n"
        f"Products: {seller.products}\nValue props: {seller.value_props}\n"
        f"Named customers: {seller.named_customers}\n"
        f"Observed industries: {industries}\nCountries: {countries}\nSize bands: {ranges}\n"
    )
    try:
        draft = llm.with_structured_output(_IcpDraft).invoke(prompt)
        if not isinstance(draft, _IcpDraft):
            draft = _IcpDraft.model_validate(draft)
    except Exception as exc:  # noqa: BLE001
        errors.append({"step": "buyer.icp_llm", "error": str(exc)})
        draft = _IcpDraft(
            industries=industries or ["Software Development"],
            countries=countries or ["United States"],
            employee_count_ranges=ranges or ["51-200", "201-500"],
            economic_buyer_titles=["VP Engineering", "CTO", "Head of Product"],
            champion_titles=["Engineering Manager", "Product Manager"],
            rationale="Fallback ICP because structured LLM output failed.",
        )

    # autocomplete validation (best effort)
    industries = _validate_autocomplete(client, "basic_info.industries", draft.industries or industries, campaign_id)
    countries = _validate_autocomplete(client, "locations.country", draft.countries or countries, campaign_id)
    ranges = _validate_autocomplete(
        client,
        "basic_info.employee_count_range",
        draft.employee_count_ranges or ranges,
        campaign_id,
    )

    low_conf = len(seller.named_customers) < 3
    evidence = list(seller.evidence[:5])
    if low_conf:
        evidence.append(
            make_evidence(
                "ICP confidence low: fewer than 3 named customers on seller site",
                source_type="user_input",
                source_ref="seller_brief",
                confidence="low",
            )
        )

    roles = [
        BuyerRole(
            title_variants=draft.economic_buyer_titles
            or ["VP Engineering", "CTO", "Chief Technology Officer"],
            kind="economic_buyer",
            why="Owns tooling budget and platform outcomes",
        ),
        BuyerRole(
            title_variants=draft.champion_titles or ["Engineering Manager", "Product Manager"],
            kind="champion",
            why="Feels day-to-day product analytics / engineering pain",
        ),
    ]

    icp = ICPProposal(
        industries=industries or ["Software Development"],
        headcount_min=None,
        headcount_max=None,
        countries=countries or ["United States"],
        funding_stages=draft.funding_stages or [],
        roles=roles,
        rationale=draft.rationale or "v0 auto-approved ICP",
        evidence=evidence,
        approved=True,  # v0: no human gate
        edited_by_user=False,
    )

    exclude = [seller.domain] + _customer_domains(customer_profiles)
    companies = _search_companies(
        client,
        icp=icp,
        ranges=ranges,
        exclude_domains=exclude,
        value_prop=(seller.value_props[0] if seller.value_props else seller.one_liner),
        n=n,
        campaign_id=campaign_id,
        events=events,
        errors=errors,
    )

    # keep top N
    companies = sorted(companies, key=lambda c: c.fit_score, reverse=True)
    kept: list[Company] = []
    for idx, company in enumerate(companies):
        if idx < n:
            company.status = "kept"
            kept.append(company)
        else:
            company.status = "dropped"
            company.drop_reason = "below_top_n"

    events.append({"type": "buyer.kept", "count": len(kept), "low_confidence_icp": low_conf})
    spent = client.ledger.spent(campaign_id)
    client.close()
    return {
        "icp": icp.model_dump(mode="json"),
        "companies": [c.model_dump(mode="json") for c in kept],
        "events": events,
        "errors": errors,
        "budget": {"credits_spent": spent},
    }


def _validate_autocomplete(
    client: CrustdataClient,
    field: str,
    values: list[str],
    campaign_id: str,
) -> list[str]:
    out: list[str] = []
    for value in values[:5]:
        try:
            result = client.company_autocomplete(
                {"field": field, "query": value, "limit": 5},
                campaign_id=campaign_id,
                step="buyer.autocomplete",
            )
            suggestions = _autocomplete_values(result)
            if suggestions:
                out.append(suggestions[0])
            else:
                out.append(value)
        except CrustdataError:
            out.append(value)
    # dedupe
    seen: set[str] = set()
    unique: list[str] = []
    for item in out:
        if item not in seen:
            seen.add(item)
            unique.append(item)
    return unique


def _search_companies(
    client: CrustdataClient,
    *,
    icp: ICPProposal,
    ranges: list[str],
    exclude_domains: list[str],
    value_prop: str,
    n: int,
    campaign_id: str,
    events: list[dict],
    errors: list[dict],
) -> list[Company]:
    hard: list[dict] = []
    if icp.industries:
        hard.append({"field": "basic_info.industries", "type": "in", "value": icp.industries[:5]})
    if icp.countries:
        hard.append({"field": "locations.country", "type": "in", "value": icp.countries[:5]})
    if ranges:
        hard.append({"field": "basic_info.employee_count_range", "type": "in", "value": ranges[:5]})
    if exclude_domains:
        hard.append(
            {
                "field": "basic_info.primary_domain",
                "type": "not_in",
                "value": exclude_domains[:50],
            }
        )

    fields = [
        "crustdata_company_id",
        "basic_info.name",
        "basic_info.primary_domain",
        "basic_info.employee_count_range",
        "locations.country",
    ]
    limit = max(n * 3, n)

    # v0 strategy B first (ranked) — simpler than competitors lookalike
    body = {
        "filters": {"op": "and", "conditions": hard} if hard else None,
        "search": {"query": value_prop or "B2B software analytics", "mode": "hybrid"},
        "fields": fields,
        "limit": min(limit, 100),
    }
    body = {k: v for k, v in body.items() if v is not None}

    try:
        result = client.company_search(body, campaign_id=campaign_id, step="buyer.search")
        rows = _company_rows(result)
        events.append({"type": "buyer.search", "strategy": "ranked", "count": len(rows)})
    except CrustdataError as exc:
        errors.append({"step": "buyer.search", "error": str(exc)})
        rows = []

    if len(rows) < n and hard:
        # fallback: filters only
        try:
            result = client.company_search(
                {
                    "filters": {"op": "and", "conditions": hard},
                    "fields": fields,
                    "limit": min(limit, 100),
                    "sorts": [{"field": "basic_info.name", "order": "asc"}],
                },
                campaign_id=campaign_id,
                step="buyer.search_filters",
            )
            rows = _company_rows(result)
            events.append({"type": "buyer.search", "strategy": "filters", "count": len(rows)})
        except CrustdataError as exc:
            errors.append({"step": "buyer.search_filters", "error": str(exc)})

    companies: list[Company] = []
    for row in rows:
        basic = row.get("basic_info") or {}
        cid = str(row.get("crustdata_company_id") or basic.get("primary_domain") or basic.get("name"))
        industry = None
        inds = basic.get("industries") or row.get("industries")
        if isinstance(inds, list) and inds:
            industry = str(inds[0])
        country = None
        locs = row.get("locations") or {}
        if isinstance(locs, dict):
            country = locs.get("country")
        elif isinstance(locs, list) and locs:
            country = locs[0].get("country") if isinstance(locs[0], dict) else None
        size = basic.get("employee_count_range")
        score = 0.0
        reasons = []
        if industry and industry in icp.industries:
            score += 0.4
            reasons.append("industry_match")
        if country and country in icp.countries:
            score += 0.3
            reasons.append("country_match")
        if size and size in ranges:
            score += 0.3
            reasons.append("size_match")
        companies.append(
            Company(
                id=cid,
                name=str(basic.get("name") or cid),
                domain=str(basic.get("primary_domain") or ""),
                industry=industry,
                headcount=None,
                country=country if isinstance(country, str) else None,
                fit_score=score,
                fit_reasons=reasons,
                status="candidate",
            )
        )
    return companies


def _autocomplete_values(payload: Any) -> list[str]:
    if isinstance(payload, list):
        out = []
        for item in payload:
            if isinstance(item, str):
                out.append(item)
            elif isinstance(item, dict):
                out.append(str(item.get("value") or item.get("name") or item.get("label") or ""))
        return [x for x in out if x]
    if isinstance(payload, dict):
        for key in ("results", "suggestions", "values", "data"):
            if key in payload:
                return _autocomplete_values(payload[key])
    return []


def _collect_ids(payload: Any) -> list[int]:
    ids: list[int] = []
    rows: list[dict] = []
    if isinstance(payload, list):
        rows = [r for r in payload if isinstance(r, dict)]
    elif isinstance(payload, dict):
        rows = [r for r in (payload.get("companies") or payload.get("results") or []) if isinstance(r, dict)]
    for row in rows:
        cid = row.get("crustdata_company_id") or row.get("company_id") or row.get("id")
        if cid is None:
            continue
        try:
            ids.append(int(cid))
        except (TypeError, ValueError):
            continue
    return ids[:25]


def _collect_company_data(payload: Any) -> list[dict]:
    out: list[dict] = []
    if isinstance(payload, list):
        for item in payload:
            if not isinstance(item, dict):
                continue
            matches = item.get("matches") or []
            if matches and isinstance(matches[0], dict):
                out.append(matches[0].get("company_data") or matches[0])
            elif "basic_info" in item:
                out.append(item)
    return out


def _company_rows(payload: Any) -> list[dict]:
    if isinstance(payload, dict):
        rows = payload.get("companies") or payload.get("results") or []
        return [r for r in rows if isinstance(r, dict)]
    if isinstance(payload, list):
        return [r for r in payload if isinstance(r, dict)]
    return []


def _industry(data: dict) -> str | None:
    tax = data.get("taxonomy") or {}
    basic = data.get("basic_info") or {}
    inds = basic.get("industries") or tax.get("professional_network_industries") or []
    if isinstance(inds, list) and inds:
        return str(inds[0])
    return None


def _country(data: dict) -> str | None:
    locs = data.get("locations") or {}
    if isinstance(locs, dict) and locs.get("country"):
        return str(locs["country"])
    if isinstance(locs, list) and locs and isinstance(locs[0], dict):
        return locs[0].get("country")
    return None


def _employee_range(data: dict) -> str | None:
    basic = data.get("basic_info") or {}
    return basic.get("employee_count_range")


def _top_values(profiles: list[dict], getter, k: int = 3) -> list[str]:
    counter: Counter[str] = Counter()
    for profile in profiles:
        value = getter(profile)
        if value:
            counter[str(value)] += 1
    return [name for name, _ in counter.most_common(k)]


def _customer_domains(profiles: list[dict]) -> list[str]:
    out = []
    for profile in profiles:
        basic = profile.get("basic_info") or {}
        domain = basic.get("primary_domain")
        if domain:
            out.append(str(domain))
    return out

"""Account researcher: per-company story and contacts (v0: sequential, person search only)."""

from __future__ import annotations

import re
from typing import Any

from app.agents.evidence import make_evidence
from app.llm import get_llm
from app.models import AccountBrief, Company, Contact, ICPProposal
from app.tools.crustdata import CrustdataClient, CrustdataError


def account_researcher_node(state: dict[str, Any]) -> dict[str, Any]:
    """v0: batch enrich kept companies, then sequential person search (no full fallback chain)."""
    campaign_id = state["campaign_id"]
    companies = [Company.model_validate(c) for c in (state.get("companies") or [])]
    icp = ICPProposal.model_validate(state["icp"])
    events = list(state.get("events") or [])
    errors = list(state.get("errors") or [])
    client = CrustdataClient()

    kept = [c for c in companies if c.status == "kept"]
    ids: list[int] = []
    for company in kept:
        try:
            ids.append(int(company.id))
        except ValueError:
            continue

    enrich_by_id: dict[str, dict] = {}
    if ids:
        try:
            enriched = client.company_enrich(
                {
                    "crustdata_company_ids": ids[:25],
                    "fields": ["basic_info", "headcount", "funding", "people", "news", "hiring"],
                },
                campaign_id=campaign_id,
                step="account.enrich",
            )
            enrich_by_id = _index_enrich(enriched)
            events.append({"type": "account.enriched", "count": len(enrich_by_id)})
        except CrustdataError as exc:
            errors.append({"step": "account.enrich", "error": str(exc)})

    titles = []
    for role in icp.roles:
        titles.extend(role.title_variants)
    titles = titles or ["CTO", "VP Engineering", "Head of Product"]

    accounts: dict[str, Any] = {}
    contacts: list[dict] = []

    for company in kept:
        data = enrich_by_id.get(str(company.id), {})
        evidence = [
            make_evidence(
                f"{company.name} is a fit candidate ({company.domain})",
                source_type="crustdata",
                source_ref=f"crustdata:/company/search:{company.id}",
                confidence="medium",
            )
        ]
        news = (data.get("news") or {}) if data else {}
        articles = []
        if isinstance(news, dict):
            articles = news.get("articles") or news.get("items") or []
        if isinstance(news, list):
            articles = news
        why_now: list[str] = []
        for article in articles[:3]:
            if not isinstance(article, dict):
                continue
            title = article.get("article_title") or article.get("title") or "Recent news"
            url = article.get("article_url") or article.get("url") or f"crustdata:/company/enrich:news"
            card = make_evidence(
                str(title)[:200],
                source_type="crustdata",
                source_ref=str(url),
                confidence="medium",
            )
            evidence.append(card)
            why_now.append(f"{title} [{card.id}]")

        if not why_now:
            why_now = [f"Active lookalike of seller ICP [{evidence[0].id}]"]

        story = _story(company, evidence, get_llm("fast"))
        brief = AccountBrief(
            company_id=company.id,
            story=story,
            why_now=why_now,
            evidence=evidence,
        )
        accounts[company.id] = brief.model_dump(mode="json")

        contact = _find_contact_v0(
            client,
            company=company,
            data=data,
            titles=titles,
            campaign_id=campaign_id,
            events=events,
            errors=errors,
        )
        if contact:
            contacts.append(contact.model_dump(mode="json"))
        else:
            events.append({"type": "account.no_contact", "company_id": company.id})

    spent = client.ledger.spent(campaign_id)
    client.close()
    return {
        "accounts": accounts,
        "contacts": contacts,
        "events": events,
        "errors": errors,
        "budget": {"credits_spent": spent},
    }


def _story(company: Company, evidence: list, llm) -> str:
    prompt = (
        "Write 3 short sentences about why this company might buy. "
        "Only use the facts below; cite evidence ids in parentheses.\n"
        f"Company: {company.name} ({company.domain})\n"
        f"Facts: {[e.fact + ' [' + e.id + ']' for e in evidence]}"
    )
    try:
        result = llm.invoke(prompt)
        text = getattr(result, "content", str(result))
        if isinstance(text, list):
            text = " ".join(str(part) for part in text)
        return str(text)[:800]
    except Exception:  # noqa: BLE001
        eid = evidence[0].id if evidence else "ev_none"
        return (
            f"{company.name} matches the seller ICP ({eid}). "
            f"They operate in {company.industry or 'a related industry'} ({eid}). "
            f"Worth a first outreach based on fit score {company.fit_score:.2f} ({eid})."
        )


def _find_contact_v0(
    client: CrustdataClient,
    *,
    company: Company,
    data: dict,
    titles: list[str],
    campaign_id: str,
    events: list[dict],
    errors: list[dict],
) -> Contact | None:
    # v0 naive: try enrich people first, else one person/search (no explain/fallback chain)
    people = data.get("people") or {}
    candidates = []
    if isinstance(people, dict):
        for key in ("decision_makers", "cxos", "founders"):
            block = people.get(key) or []
            if isinstance(block, list):
                candidates.extend([p for p in block if isinstance(p, dict)])

    picked = _pick_by_title(candidates, titles)
    profile_url = None
    name = None
    title = None
    if picked:
        name = picked.get("name") or picked.get("full_name")
        title = picked.get("title") or picked.get("current_title") or "Leader"
        profile_url = (
            picked.get("profile_url")
            or picked.get("linkedin_profile_url")
            or picked.get("professional_network_url")
        )
        events.append({"type": "account.contact_from_people", "company_id": company.id})

    if not profile_url:
        try:
            company_id_int = int(company.id)
        except ValueError:
            return None
        title_conditions = [
            {
                "field": "experience.employment_details.current.title",
                "type": "[.]",
                "value": t,
            }
            for t in titles[:6]
        ]
        body = {
            "filters": {
                "op": "and",
                "conditions": [
                    {
                        "field": "experience.employment_details.current.company_id",
                        "type": "=",
                        "value": company_id_int,
                    },
                    {
                        "field": "experience.employment_details.current.is_default",
                        "type": "=",
                        "value": True,
                    },
                    {"op": "or", "conditions": title_conditions},
                    {"field": "contact.has_business_email", "type": "=", "value": True},
                ],
            },
            "fields": [
                "crustdata_person_id",
                "basic_profile.name",
                "basic_profile.current_title",
                "social_handles.professional_network_identifier.profile_url",
                "contact.has_business_email",
            ],
            "limit": 5,
        }
        try:
            result = client.person_search(body, campaign_id=campaign_id, step="account.person_search")
            profiles = result.get("profiles") if isinstance(result, dict) else []
            if profiles:
                person = profiles[0]
                basic = person.get("basic_profile") or {}
                name = basic.get("name") or person.get("name")
                title = basic.get("current_title") or person.get("title") or titles[0]
                social = person.get("social_handles") or {}
                pn = social.get("professional_network_identifier") or {}
                profile_url = pn.get("profile_url") or person.get("profile_url")
                events.append({"type": "account.contact_from_search", "company_id": company.id})
        except CrustdataError as exc:
            errors.append({"step": "account.person_search", "error": str(exc), "company_id": company.id})
            return None

    if not name:
        return None

    email = None
    email_source = "none"
    email_confidence = "none"
    if profile_url:
        try:
            enriched = client.person_enrich(
                {
                    "professional_network_profile_urls": [profile_url],
                    "fields": ["basic_profile", "experience", "contact.business_emails"],
                },
                campaign_id=campaign_id,
                step="account.person_enrich",
            )
            email = _extract_email(enriched)
            if email:
                email_source = "crustdata"
                email_confidence = "likely"
        except CrustdataError as exc:
            errors.append({"step": "account.person_enrich", "error": str(exc)})

    contact_id = f"{company.id}:{_slug(name)}"
    return Contact(
        id=contact_id,
        company_id=company.id,
        name=str(name),
        title=str(title or "Leader"),
        role_kind="economic_buyer",
        email=email,
        email_source=email_source,  # type: ignore[arg-type]
        email_confidence=email_confidence,  # type: ignore[arg-type]
        profile_url=profile_url,
    )


def _pick_by_title(people: list[dict], titles: list[str]) -> dict | None:
    lowered = [t.lower() for t in titles]

    def score(person: dict) -> int:
        title = str(person.get("title") or person.get("current_title") or "").lower()
        return sum(1 for t in lowered if t in title)

    ranked = sorted(people, key=score, reverse=True)
    if ranked and score(ranked[0]) > 0:
        return ranked[0]
    return ranked[0] if ranked else None


def _index_enrich(payload: Any) -> dict[str, dict]:
    out: dict[str, dict] = {}
    if not isinstance(payload, list):
        return out
    for item in payload:
        if not isinstance(item, dict):
            continue
        matches = item.get("matches") or []
        if not matches:
            continue
        data = matches[0].get("company_data") or matches[0]
        cid = data.get("crustdata_company_id") or (data.get("basic_info") or {}).get("company_id")
        if cid is not None:
            out[str(cid)] = data
    return out


def _extract_email(payload: Any) -> str | None:
    text = str(payload)
    match = re.search(r"[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}", text)
    return match.group(0) if match else None


def _slug(name: str) -> str:
    return re.sub(r"[^a-z0-9]+", "-", name.lower()).strip("-")[:40]

